const xsIsAddr = s => /^0x[0-9a-fA-F]{40}$/.test((s||'').trim());
const xsP = id => XS_PEOPLE.find(p=>p.id===id);
const xsByAddr = a => XS_PEOPLE.find(p=>p.addr && p.addr.toLowerCase()===String(a).trim().toLowerCase());
const xsInit = () => { if (!S.xs) S.xs = {q:'', to:null, ext:null, amt:'', note:'', ack:false}; return S.xs; };
const xsTo = () => { const x = xsInit(); return x.to ? xsP(x.to) : x.ext ? {n:'External wallet', ext:true, addr:x.ext} : null; };
const xsFirst = () => { const x = xsInit(); return x.ext ? true : !XS_RECENT.includes(x.to); };
const xsFees = a => { const r = (typeof RATE!=='undefined' && RATE[xsTokSym()]) || 1; const fee = a>0 ? Math.round(feeFor(a*r)/r*100)/100 : 0; const gas = a>0 && !xsFromExt() ? Math.round(GAS/r*100)/100 : 0; return {fee, gas, total: Math.round((a+fee+gas)*100)/100}; }; // on-chain transfer: tier payment fee + network gas (V2 keeps gas here, Scan and Pay has none)
const xsAvail = () => { const t = T(), b = xsFromBal(); const c1 = Math.floor((b-GAS)/(1+t.fee/100)*100)/100;
  const v = c1*t.fee/100 >= t.floor ? c1 : Math.floor((b-GAS-t.floor)*100)/100; return Math.max(0, v); };
const xsFeeRows = (a, cls='kv') => { const t = T(); const f = xsFees(a);
  return `<div class="${cls}"><span class="sp-pf">Payment fee ${tierBadge(t)}</span><b><i class="sp-pct g">${t.fee.toFixed(2)}%</i>${f.fee.toFixed(2)}</b></div><div class="${cls}"><span>Gas fee</span><b>${f.gas.toFixed(2)}</b></div>`; };
const xsErr = () => { const a = +(xsInit().amt||0); if (!a) return ''; if (a < XS_MIN) return `Minimum is ${xsTokSym()} ${XS_MIN.toFixed(2)}.`;
  if (xsFees(a).total > xsFromBal()) return `Not enough ${xsTokSym()}. With fees this needs ${xsMoney(xsFees(a).total)}.`; return ''; };
const xsAv = (p, cls='') => p.ext ? `<span class="xs-avx ${cls}">${ic('xsWallet')}</span>` : `<span class="xs-av ${cls}">${img(p.av,p.n)}</span>`;
const xsName = p => `${esc(p.n)}${p.v?`<span class="vbdg" aria-label="Verified">${ic('verify')}</span>`:''}`;
const xsMoney = v => xsTokSym()+' '+(+v).toLocaleString('en-MY',{minimumFractionDigits:2, maximumFractionDigits:2});

/* 1 · Send to */
V.xsTo = () => { const x = xsInit(); const q = x.q.trim(); const ql = q.toLowerCase().replace(/[\s-]/g,'');
  const isA = xsIsAddr(q), looksA = /^0x/i.test(q) && !isA; const own = isA && q.toLowerCase()===XS_ME.addr.toLowerCase(); const hit = isA ? xsByAddr(q) : null;
  const list = !q ? XS_PEOPLE : XS_PEOPLE.filter(p => p.n.toLowerCase().includes(q.toLowerCase()) || p.h.includes(q.toLowerCase()) || p.ph.replace(/[\s-]/g,'').includes(ql));
  const row = p => `<button class="xs-row ${p.addr?'':'off'}" data-act="xsPick" data-id="${p.id}">${xsAv(p)}<span class="xs-rt"><b>${xsName(p)}</b><small>${p.addr ? `${p.h} · ${xsShort(p.addr)}` : `${p.h} · Wallet not activated yet`}</small></span>${p.addr?ic('chev'):''}</button>`;
  let body;
  if (isA) body = own ? `<div class="xs-note err">${ic('alert')}<span>This is your own wallet address. Enter someone else’s.</span></div>`
    : hit ? `<p class="xs-sec">YouApp user</p><div class="xs-list">${row(hit)}</div><p class="xs-tip">${ic('check')}This address belongs to ${esc(hit.n)} on YouApp.</p>`
    : `<p class="xs-sec">Wallet address</p><div class="xs-list"><button class="xs-row" data-act="xsPickAddr">${xsAv({ext:true})}<span class="xs-rt"><b>Send to this address</b><small class="mono">${xsShort(q)} · Ethereum</small></span>${ic('chev')}</button></div>`;
  else if (looksA) body = `<div class="xs-note err">${ic('alert')}<span>That doesn’t look like a full Ethereum address. It should start with 0x and have 42 characters.</span></div>`;
  else body = `${!q?`<p class="xs-sec">Recent</p><div class="xs-rec">${XS_RECENT.map(id=>{ const p = xsP(id); return `<button data-act="xsPick" data-id="${p.id}">${xsAv(p,'lg')}<small>${esc(p.n.split(' ')[0])}</small></button>`; }).join('')}</div>`:''}
    <p class="xs-sec">${q?'Results':'YouApp friends'}</p>${list.length?`<div class="xs-list">${list.map(row).join('')}</div>`:`<div class="xs-empty"><b>No one found</b><small>Try a name, @handle or phone number, or paste a wallet address.</small></div>`}`;
  return `<div class="screen bz">${statusBar()}${topBar('Send')}
  <div class="scroll"><div class="pad16 stack" style="gap:12px; padding-top:4px">
    <label class="xs-search">${ic('search')}<input id="xsQ" data-in="xsQ" value="${esc(x.q)}" placeholder="Name, @handle, phone or 0x address" autocomplete="off" spellcheck="false" aria-label="Search recipient">${q?`<button data-act="xsClear" aria-label="Clear">${ic('close')}</button>`:''}</label>
    <div class="xs-quick"><button data-act="xsScan">${ic('scan')}Scan QR</button><button data-act="xsPaste">${ic('copy')}Paste address</button></div>
    ${body}
  </div></div></div>`; };

/* 2 · Amount */
V.xsAmt = () => { const x = xsInit(); const p = xsTo(); const a = x.amt||''; const err = xsErr(); const ok = +a>0 && !err;
  const scanned = x.src==='scan' ? `<div class="xs-scan">${ic('scan')}<span>${p.ext?'Wallet address QR scanned.':'YouApp QR scanned.'} You’re sending MYRT, not paying a merchant.</span></div>` : '';
  return `<div class="screen bz xs-amtscr">${statusBar()}${topBar('Send')}
  <div class="scroll"><div class="pad16 stack" style="gap:16px; padding-top:8px; padding-bottom:20px">
    ${scanned}
    <button class="xs-to" data-act="xsChange">${xsAv(p)}<span class="xs-rt"><b>${p.ext?'External wallet':xsName(p)}</b><small class="mono">${p.ext?'':esc(p.h)+' · '}${xsShort(p.addr)}</small></span><em>Change</em></button>
    ${xsFirst() ? `<div class="xs-note warn">${ic('info')}<span>${p.ext?'First time sending to this address. Check every character before you send.':`First time sending to ${esc(p.n.split(' ')[0])}. Make sure it’s the right person.`}</span></div>`:''}
    ${mwSendRows()}<div class="xs-amt ${err?'err':''}"><small>You send</small><div><span>${xsTokSym()}</span><b class="${a?'':'ph'}">${a||'0.00'}</b></div>
      <span class="xs-av2">${err?`<em class="xs-e">${err}</em>`:`Available ${xsMoney(xsFromBal())}`}<button data-act="xsMax">Max</button></span>${+a>0&&!err?`<span class="xs-tot">+ fees ${xsMoney(xsFees(+a).fee+xsFees(+a).gas)} · Total ${xsMoney(xsFees(+a).total)}</span>`:''}</div>
    <div class="xs-nw"><label class="xs-notein">${ic('edit')}<input id="xsNote" data-in="xsNote" maxlength="60" value="${esc(x.note)}" placeholder="Add a note (optional)" aria-label="Note"></label>
    <small class="xs-cap">${p.ext?'Notes stay in YouApp. They aren’t stored on-chain.':`Only you and ${esc(p.n.split(' ')[0])} see the note. It isn’t stored on-chain.`}</small></div>
  </div></div>
  <div class="w2foot">${btn('Review', ok?'xsReview':'noop', {disabled:!ok})}</div>
  ${keypad('xk')}</div>`; };

/* 3 · Review (sheet) */
SHEETS.xsReview = () => { const x = xsInit(); const p = xsTo(); const a = +x.amt; const need = p.ext;
  return `<div class="grab"></div><div class="stack" style="gap:14px">
    <div class="xs-rvh">${xsAv(p,'lg')}<small>You’re sending</small><b>${xsMoney(a)}</b><span>to ${p.ext?'an external wallet':xsName(p)}</span></div>
    <div class="kvbox sp-box xs-kv">
      <div class="kv"><span>To</span><b>${p.ext?'External wallet':esc(p.n)}</b></div>
      <div class="kv"><span>Wallet address</span><b class="mono">${xsShort(p.addr)}</b></div>
      <div class="kv"><span>Network</span><b>Ethereum · ERC-20</b></div>
      ${xsFeeRows(a)}
      <div class="kv"><span>Arrives in</span><b>About 1 minute</b></div>
      ${x.note?`<div class="kv"><span>Note</span><b>${esc(x.note)}</b></div>`:''}
      <div class="kv tot"><span>Total</span><b>${xsMoney(xsFees(a).total)}</b></div></div>
    ${need ? `<button class="xs-ack ${x.ack?'on':''}" data-act="xsAck" role="checkbox" aria-checked="${x.ack}"><i>${ic('check')}</i><span>I’ve checked this address supports ${xsTokSym()} on Ethereum. Sending to the wrong address or network can’t be undone.</span></button>`
      : `<p class="xs-irr">${ic('lock')}On-chain transfers can’t be reversed once sent.</p>`}
    ${btn('Send '+xsMoney(a), !need||x.ack?'xsConfirm':'noop', {disabled: need && !x.ack})}</div>`; };

/* 4 · PIN */
V.xsPin = () => { const n = (S.xsPin||'').length;
  return `<div class="screen">${statusBar()}${topBar('Confirm Transfer')}
  <div class="scroll"><div class="pad16 stack" style="align-items:center; text-align:center; gap:10px; padding-top:20px">
    <b class="t-headline">Enter Your PIN</b><p class="t-body muted" style="margin:0">To send ${xsMoney(+xsInit().amt)} to ${esc(xsTo().ext?xsShort(xsTo().addr):xsTo().n)}</p>
    <div class="pin-dots ${S.xsPinErr?'err':''}">${[0,1,2,3,4,5].map(i=>`<i class="${i<n?'on':''}"></i>`).join('')}</div>
    ${S.xsPinErr?'<small class="sp-err">Wrong PIN. 4 tries left.</small>':''}
    <template data-demo-input>Use 123456 to continue. Enter 000000 to test a wrong PIN.</template></div></div>
  ${keypad('xp')}</div>`; };

/* 5 · On-chain progress */
const XS_HASH = '0x9c4e2b7f1a8d3c6e5b0a9f8e7d6c5b4a3f2e1d0c9b8a7f6e5d4c3b2a1f0eb71a';
V.xsProc = () => { const x = xsInit(); const p = xsTo(); const r = x.run || {st:0, conf:0}; const slow = scen.xsRes==='slow' && r.st===2 && r.conf>=3;
  const steps = [['Signed','Approved with your PIN'],['Submitted to Ethereum', r.st>=1?`Tx ${xsShort(XS_HASH)}`:'Broadcasting…'],['Confirming', r.st>=2?`${r.conf} of 12 confirmations`:'Waiting for a block'],['Sent', r.st>=3?`${esc(p.ext?xsShort(p.addr):p.n)} has it`:'Lands in their wallet']];
  return `<div class="screen bz">${statusBar()}${topBar('Send')}
  <div class="scroll"><div class="pad16 stack" style="gap:14px; padding-top:8px">
    <div class="xs-ph">${xsAv(p,'lg')}<b>${xsMoney(+x.amt)}</b><small>to ${p.ext?xsShort(p.addr):esc(p.n)}</small></div>
    <ol class="xs-steps">${steps.map(([a,b],i)=>`<li class="${i<r.st?'done':i===r.st?'xs-cur':''}"><i>${i<r.st?ic('check'):''}</i><span><b>${a}</b><small>${b}</small>${i===2&&r.st===2?`<em class="xs-bar"><s style="width:${r.conf/12*100}%"></s></em>`:''}</span></li>`).join('')}</ol>
    ${slow?`<div class="xs-note warn">${ic('clock')}<span>The network is busy, so this is taking longer than usual. Your MYRT is safe. You can leave and we’ll let you know when it lands.</span></div>`:''}
    ${r.st>=1?`<button class="xs-hash" data-act="xsScanTx">${ic('xsExt')}View on Etherscan</button>`:''}
  </div></div>
  <div class="w2foot">${btn('Back to Wallet','xsLeave',{kind:'btn-secondary'})}<p class="t-caption subtle" style="margin:0; text-align:center">You can leave this screen. We’ll notify you when it lands.</p></div></div>`; };
const xsRun = () => { const x = xsInit(); x.run = {st:0, conf:0, t:Date.now()}; clearInterval(S.xsT);
  const res = scen.xsRes || 'ok'; let tick = 0;
  S.xsT = setInterval(() => { const r = x.run; tick++;
    if (r.st===0 && tick>=2) r.st = 1;
    else if (r.st===1 && tick>=4) { if (res==='fail') { clearInterval(S.xsT); x.fail = true; xsFinish(); return; } r.st = 2; r.conf = 1; }
    else if (r.st===2) { if (res==='slow' && r.conf===3 && tick<20) {} else r.conf = Math.min(12, r.conf+1); if (r.conf>=12) r.st = 3; }
    else if (r.st===3) { clearInterval(S.xsT); xsFinish(); return; }
    if (S.screen==='xsProc') render(); }, 380); };
const xsFinish = () => { const x = xsInit(); const p = xsTo();
  if (S.screen==='xsProc') { go(x.fail?'xsFail':'xsDone', {replace:true}); return; }
  if (x.fail) toast(`Transfer didn’t go through. ${xsMoney(+x.amt)} is back in your wallet.`, 'err');
  else toast(`${xsMoney(+x.amt)} sent to ${p.ext?xsShort(p.addr):p.n}.`); x.bgDone = true; };

/* 6 · Result */
V.xsDone = () => { const x = xsInit(); const p = xsTo(); const a = +x.amt;
  return `<div class="screen bz">${statusBar()}${topBar('Send')}
  <div class="scroll"><div class="success" style="padding-top:4px">${cele()}<b class="bl-ok">Sent</b><b class="sp-big">${xsMoney(a)}</b><span class="t-body subtle">to ${p.ext?'external wallet '+xsShort(p.addr):esc(p.n)+' · '+esc(p.h)}</span></div>
  <div class="pad16 stack" style="padding-top:10px; gap:10px"><div class="kvbox sp-box">
    <div class="kv"><span>To</span><b class="mono">${xsShort(p.addr)}</b></div>
    ${xsFeeRows(a)}
    <div class="kv"><span>Total</span><b>${xsMoney(xsFees(a).total)}</b></div>
    <div class="kv"><span>Tx hash</span><b><button class="xs-lnk" data-act="xsScanTx">${xsShort(XS_HASH)}${ic('xsExt')}</button></b></div>
    <div class="kv"><span>Network</span><b>Ethereum · ERC-20</b></div>
    <div class="kv"><span>Reference</span><b>YA-2710-2206</b></div>
    <div class="kv"><span>Date</span><b>27 Oct 2026, 11:04 pm</b></div>
    ${x.note?`<div class="kv"><span>Note</span><b>${esc(x.note)}</b></div>`:''}</div>
    ${p.ext?'':`<p class="t-caption subtle" style="margin:0; text-align:center">${esc(p.n.split(' ')[0])} gets a notification that the MYRT has landed.</p>`}
  </div></div>
  <div class="w2foot">${btn('Done','xsDoneGo')}${btn('Share this moment','xsShare',{kind:'btn-secondary'})}</div></div>`; };
V.xsFail = () => { const x = xsInit(); const p = xsTo();
  return `<div class="screen bz">${statusBar()}${topBar('Send')}
  <div class="scroll"><div class="success"><span class="big err">${ic('xcircle')}</span><b class="t-headline">Transfer didn’t go through</b>
    <span class="t-body muted">The Ethereum network rejected it. ${xsMoney(+x.amt)} is back in your wallet. The payment fee is refunded too. The gas fee of ${xsMoney(GAS)} was used by the network and can’t be refunded.</span></div>
    <div class="pad16"><div class="kvbox sp-box"><div class="kv"><span>To</span><b>${p.ext?xsShort(p.addr):esc(p.n)}</b></div><div class="kv"><span>Tx hash</span><b><button class="xs-lnk" data-act="xsScanTx">${xsShort(XS_HASH)}${ic('xsExt')}</button></b></div><div class="kv"><span>Status</span><b style="color:#b3261e">Failed</b></div></div></div></div>
  <div class="w2foot">${btn('Try Again','xsRetry')}${btn('Back to Wallet','xsDoneGo',{kind:'btn-tertiary'})}</div></div>`; };

/* Receive */
V.xsRecv = () => `<div class="screen bz">${statusBar()}${topBar('My QR')}
  <div class="scroll"><div class="pad16 stack" style="gap:14px; padding-top:8px; padding-bottom:20px">
    <section class="xs-qr"><div class="xs-qrb">${qrSvg(311)}<span class="xs-qrav">${img('avatar','Elsa')}</span></div>
      <b>${XS_ME.n}<span class="vbdg" aria-label="Verified">${ic('verify')}</span></b><small>${XS_ME.h} · Scan to send me stablecoins</small></section>
    <div class="xs-addr"><small>Your wallet address · Ethereum</small><b class="mono">${xsChunk(XS_ME.addr)}</b>
      <button data-act="xsCopy" data-v="${XS_ME.addr}">${ic('copy')}Copy Address</button></div>
    <div class="xs-acc"><span class="xs-tk">${['MYRT','XSGD','USDT','USDC'].map(k=>`<img src="${XS_TOK[k]}" alt="${k}">`).join('')}</span><span><b>Accepts MYRT, XSGD, USDT and USDC</b><small>Ethereum (ERC-20) only. XSGD, USDT and USDC convert to MYRT on arrival. YouApp fee 0%.</small></span></div>
  </div></div>
  <div class="w2foot xs-2b">${btn(ic('share')+'Share QR','toast',{kind:'btn-secondary', data:'data-msg="Opens the share sheet with your QR and address."'})}${btn(ic('xsUp')+'Send MYRT','xsOpen')}</div></div>`;
V.myQr = V.xsRecv;
const XS_TOK = {XSGD:'data:image/webp;base64,', MYRT:'data:image/png;base64,', USDT:'data:image/webp;base64,', USDC:'data:image/png;base64,'}; window.XS_TOKW = XS_TOK;
/* Scan → route by QR type */
SHEETS.scanSim = () => `<div class="grab"></div><div class="stack" style="gap:10px"><div><h2 class="t-title" style="margin:0">What did the camera see?</h2><template data-demo-input>Select a sample QR to test Pay or Send.</template></div>
  <div class="xs-list">${[['duit','DuitNow QR','Kopitiam Lee · enter amount','scan'],['duitFixed','DuitNow QR (Fixed Amount)','Mydin Mart · RM45.90','scan'],['duitPersonal','Personal DuitNow QR','Ali Rahman · enter amount','person'],['ya','YouApp wallet QR','Catherine Lee · goes to Send MYRT','xsWallet'],['addr','Ethereum address QR','External wallet · goes to Send MYRT','xsExt'],['bad','Unsupported QR','A website link']].map(([k,a,b,i])=>`<button class="xs-row" data-act="scanAs" data-k="${k}"><span class="xs-avx">${ic(i||'alert')}</span><span class="xs-rt"><b>${a}</b><small>${b}</small></span>${ic('chev')}</button>`).join('')}</div></div>`;

Object.assign(A, {
  xsOpen: el => {
    if (!kycOk()) { toast('Verify your identity to send MYRT.','err'); return; }
    S.xs = null;
    const draft = xsInit();
    const wallet = el?.dataset?.fromWallet;
    if (wallet && wIds().includes(wallet)) draft.from = wallet;
    go('xsTo');
  },
  xsRecv: () => { if (!kycOk()) { toast('Verify your identity to receive MYRT.','err'); return; } go('xsRecv'); },
  xsClear: () => { xsInit().q=''; render(); },
  xsPaste: () => { xsInit().q = XS_EXT; render(); },
  xsScan: () => { S.sheet='scanSim'; render(); },
  xsPick: el => { const p = xsP(el.dataset.id); if (!p.addr) { toast(`${p.n} hasn’t activated a YouApp wallet yet. Ask them to verify first.`,'err'); return; }
    const x = xsInit(); x.to = p.id; x.ext = null; x.src = null; x.amt=''; x.ack=false; go('xsAmt'); },
  xsPickAddr: () => { const x = xsInit(); x.ext = x.q.trim(); x.to = null; x.src=null; x.amt=''; x.ack=false; go('xsAmt'); },
  xsChange: () => { const x = xsInit(); if (S.hist[S.hist.length-1]==='xsTo') A.back(); else { S.screen='xsTo'; render(); } },
  xk: el => { const x = xsInit(); const k = el.dataset.k; let v = x.amt||''; const [w,d] = v.split('.');
    if (k==='.') { if (!v.includes('.')) v = (v||'0')+'.'; } else if (d!==undefined && d.length>=2) return; else if (!v.includes('.') && w.length>=7) return; else v = (v==='0'?'':v)+k;
    x.amt = v; render(); },
  xkDel: () => { const x = xsInit(); x.amt = (x.amt||'').slice(0,-1); render(); },
  xsMax: () => { xsInit().amt = xsAvail().toFixed(2); render(); },
  xsReview: () => { S.sheet='xsReview'; render(); },
  xsAck: () => { const x = xsInit(); x.ack = !x.ack; render(); },
  xsConfirm: () => { S.sheet=null; S.xsPin=''; S.xsPinErr=false; go('xsPin'); },
  xp: el => { if ((S.xsPin||'').length>=6) return; S.xsPin = (S.xsPin||'')+el.dataset.k; S.xsPinErr=false;
    if (S.xsPin.length===6) { if (S.xsPin==='000000') { S.xsPinErr=true; S.xsPin=''; render(); return; } const x = xsInit(); x.fail=false; x.bgDone=false; go('xsProc',{replace:true}); xsRun(); return; } render(); },
  xpDel: () => { S.xsPin = (S.xsPin||'').slice(0,-1); render(); },
  xsLeave: () => { S.hist = S.hist.filter(s=>!/^xs/.test(s)); S.screen = 'home'; S.sheet=null; render(); toast('Sending in the background. We’ll let you know when it lands.'); },
  xsDoneGo: () => { S.hist = S.hist.filter(s=>!/^xs/.test(s)); S.screen = 'home'; render(); },
  xsRetry: () => { const x = xsInit(); x.fail=false; S.xsPin=''; go('xsAmt',{replace:true}); },
  xsScanTx: () => toast('Opens the transaction on Etherscan.'),
  xsCopy: async el => {
    try {
      await navigator.clipboard.writeText(el.dataset.v);
      toast('Address copied.');
    } catch {
      toast('Couldn’t copy the wallet address. Try again.', 'err');
    }
  },
  xsShare: () => { const x = xsInit(); const p = xsTo(); const a = +x.amt; if (!window.SHR) return;
    SHR.open({title:'Sent', amount:xsMoney(a), sub: p.ext?'to an external wallet · Ethereum':`to ${p.n} · YouApp transfer`, ref:'YA-2710-2206', caption:"Sent MYRT to a friend in seconds, right on-chain ⚡ Try YouApp for the easiest way to move ringgit.",
      tx:[['Reference','YA-2710-2206'],['Tx Hash',xsShort(XS_HASH),'lnk'],['Transaction Type','MYRT transfer'],['Timestamp','27 Oct 2026, 11:04 PM']],
      pay:[['Amount',xsMoney(a)],['Payment fee',`${T().fee.toFixed(2)}% · ${xsFees(a).fee.toFixed(2)}`],['Gas fee',GAS.toFixed(2)]], total:['Total',xsMoney(xsFees(a).total)]}); },
  scanAs: el => { const k = el.dataset.k; S.sheet=null;
    const merchants = {duit:'kopi', duitFixed:'mydin', duitPersonal:'ali'};
    if (merchants[k]) { A.scanQr({dataset:{id:merchants[k]}}); return; }
    if (k==='bad') { render(); toast('This QR isn’t a DuitNow or YouApp wallet QR.','err'); return; }
    const x = (S.xs = null, xsInit()); x.src='scan';
    if (k==='ya') x.to='cath'; else x.ext = XS_EXT;
    go('xsAmt'); },
});
/* camera tap on Scan now asks what the QR is (demo), so DuitNow → Pay and YouApp/0x → Send */
{ const _sc = V.scan; V.scan = () => { let s = _sc().replace('data-act="scanQr" data-id="kopi"', 'data-act="sheet" data-s="scanSim"');
  if (scen.kyc==='passed') s = s.replace(/(<div class="sp-acts">[\s\S]*?data-s="gallery"[\s\S]*?<\/button><\/div>)/, `$1<button class="sp-addr" data-act="xsAddr">Enter wallet address${ic('chev')}</button>`);
  return s; }; }
V.xsAddr = () => { const x = xsInit(); const v = (x.addr||'').trim(); const ok = xsIsAddr(v); const own = ok && v.toLowerCase()===XS_ME.addr.toLowerCase(); const hit = ok ? xsByAddr(v) : null;
  const err = !v ? '' : own ? 'This is your own wallet address.' : !/^0x/i.test(v) ? 'Ethereum addresses start with 0x.' : !ok ? `Check the address. It should be 42 characters (you have ${v.length}).` : '';
  return `<div class="screen bz">${statusBar()}${topBar('Send')}
  <div class="scroll"><div class="pad16 stack" style="gap:12px; padding-top:4px">
    <div><h2 class="t-title" style="margin:0">Enter wallet address</h2><p class="t-caption subtle" style="margin:4px 0 0">Send MYRT to any Ethereum (ERC-20) wallet, including a YouApp user’s.</p></div>
    <div class="field ${err?'err':''}"><div class="xs-ain"><template data-demo-input>Sample external wallet address: ${XS_EXT}</template><textarea id="xsA" data-in="xsA" rows="2" placeholder="0x…" autocomplete="off" spellcheck="false" aria-label="Wallet address">${esc(x.addr||'')}</textarea><button data-act="${v?'xsAClear':'xsAPaste'}">${v?'Clear':'Paste'}</button></div>
      ${err?`<span class="helper">${err}</span>`:ok?'':'<span class="helper neutral">Ethereum mainnet · ERC-20 only. Starts with 0x, 42 characters.</span>'}</div>
    ${hit?`<div class="xs-list"><div class="xs-row">${xsAv(hit)}<span class="xs-rt"><b>${xsName(hit)}</b><small>${hit.h} · YouApp user</small></span></div></div><p class="xs-tip">${ic('check')}This address belongs to ${esc(hit.n)} on YouApp.</p>`
      : ok && !own ? `<div class="xs-list"><div class="xs-row">${xsAv({ext:true})}<span class="xs-rt"><b>External wallet</b><small class="mono">${xsShort(v)} · Ethereum</small></span></div></div><div class="xs-note warn">${ic('info')}<span>Make sure this wallet accepts MYRT on Ethereum. Transfers can’t be reversed.</span></div>` : ''}
  </div></div>
  <div class="w2foot">${btn('Continue', ok&&!own?'xsAGo':'noop', {disabled:!ok||own})}</div></div>`; };
Object.assign(A, {
  xsAddr: () => { S.xs = null; xsInit().addr=''; go('xsAddr'); },
  xsAPaste: () => { xsInit().addr = XS_EXT; render(); },
  xsAClear: () => { xsInit().addr = ''; render(); },
  xsAGo: () => { const x = xsInit(); const v = x.addr.trim(); const hit = xsByAddr(v); x.to = hit ? hit.id : null; x.ext = hit ? null : v; x.src = null; x.amt=''; x.ack=false; go('xsAmt'); },
});
